#!/usr/bin/env python3
"""A.C.E. 1.6.1 — workspace navigation, chats/projects, attachments and Live preview.

Loads 1.6.0 cumulatively, then adds the new left workspace rail/drawer, persistent
chats and projects, AI Search, attachment chips/previews, and Live-mode chat/project/
work metadata with a slide-out artifact preview. Existing Update, Voice, Stop, Chat/
Live, artifact generation, editing and downloads remain on the proven 1.6.0 runtime.
"""
from pathlib import Path
import base64, importlib.util, zlib

H=Path(__file__).resolve().parent
BASE=H/'ACE Base 1.6.0.py'
spec=importlib.util.spec_from_file_location('ace_base_160',str(BASE))
b160=importlib.util.module_from_spec(spec);spec.loader.exec_module(b160)
ace=b160.ace
ace.VERSION='1.6.1'
try: ace.UPDATE_STATE['current_version']='1.6.1'
except Exception: pass

def patch(path,marker,transform):
    try:
        p=Path(path);s=p.read_text(encoding='utf-8')
        if marker in s:return True
        n=transform(s)
        if n!=s:p.write_text(n,encoding='utf-8')
        return marker in n
    except Exception:return False

def idx161(s):
    s=s.replace('app.css?v=160-corefix','app.css?v=161-workspace')
    s=s.replace('app.js?v=160-corefix','app.js?v=161-workspace')
    s=s.replace('Current version: v1.6.0','Current version: v1.6.1')
    return s+'\n<!--ACE161_WORKSPACE-->\n'

CSS161=zlib.decompress(base64.b64decode('')).decode('utf-8')
JS161=zlib.decompress(base64.b64decode('')).decode('utf-8')
patch(H/'index.html','ACE161_WORKSPACE',idx161)
patch(H/'app.css','ACE161_WORKSPACE',lambda s:s+'\n'+CSS161+'\n')
patch(H/'app.js','ACE161_WORKSPACE',lambda s:s+'\n'+JS161+'\n')

if __name__=='__main__':ace.main()
